/**
 * TEX'S ONE CONFIG, AS THE GATEWAY READS IT (Dev2, 2026-11-13: "I want the config generated by the lab to become the
 * production code, and to be the only source of truth").
 *
 * `packages/tex/src/texConfig.json` is the Tex Architecture Lab's graph of main: every step's model, effort, on or
 * off, time limit and the context it reads, and every wire. The Lab opens it as main and promotes a version by
 * changing it in a pull request, so the replay gate stands between a Lab edit and a live turn. Each model-calling
 * file asks this module for its step's model, effort and time limit instead of keeping a constant of its own, and the
 * texting setup's models come from here, not from the setup note (`production.js`). It asks with the turn's config
 * (`texConfigOf`): main's, or in a Lab test chat the draft's over main's, so a draft runs whole there.
 *
 * Wires still run as code. A step the code has no way to run when on (the router, for now) is refused by
 * `test/texConfig.test.mjs`, so the file never says something the gateway does not do.
 */
import { TEX_CONFIG as CONFIG } from "../../../../packages/tex/src/texConfig.cjs";
import PROMPT from "../../../../packages/tex/src/texPrompt.generated.json" with { type: "json" };
import GENERATED_TRAINING from "../../../../packages/tex/src/texTraining.generated.json" with { type: "json" };
import SHELF from "../../../../packages/tex/src/texNodeShelf.json" with { type: "json" };
import { TRAIN_ENTRY, trainingOf, moduleText, trainName } from "../../../../packages/tex/src/texTraining.cjs";
import { DOORS, DOOR_NODES } from "./doorTools.js";

/** Every Training conversation, less what a bench process scores of it (`texTraining.cjs` `trainingOf`; production reads all). */
export const TRAINING = trainingOf(GENERATED_TRAINING);
import { configStamp } from "../../../../packages/tex/src/texConfigStamp.cjs";
import { runOrder } from "../../../../packages/tex/src/texModuleChange.cjs";
import { sandboxGateOf } from "../labSandbox/policy.js";
import { EFFORTS as SCHEMA_EFFORTS } from "../../../../packages/tex/src/texConfigSchema.cjs";

export const TEX_CONFIG = CONFIG;
/** The stamp of the config this code runs: a draft made from main keeps it, so Promote merges only its own changes (`texConfigStamp.cjs`). */
export const CONFIG_STAMP = configStamp(CONFIG);

/**
 * Steps on the shelf (`texNodeShelf.json`; Dev2, 2026-11-16: "for code changes, create the node inside the code first
 * and merge it to main"): their code is merged and main's config has no node for them, so live Tex never runs them, and
 * a Lab draft that draws them runs them (`withDraft`). Promote takes each off the shelf as it puts it in the config.
 */
export const SHELF_NODES = Object.freeze(Object.keys(SHELF.nodes ?? {}));

/**
 * Steps retired off the config (Dev2, 2026-11-20: "we can leave the underlying code in the code base, just not wire it
 * anywhere"): on the shelf with `retired: true` and their last definition as `node`, off, never drawn and never run by
 * the runner. Code that still reads a setting off one (a model, a time limit, a schema) reads it here.
 */
export const RETIRED_STEPS = Object.freeze(Object.fromEntries(Object.entries(SHELF.nodes ?? {}).filter(([, entry]) => entry?.retired === true && entry.node?.id).map(([id, entry]) => [id, Object.freeze({ ...entry.node, on: false })])));

/**
 * Tex's prompt words by module name: the repository's, from `packages/tex/src/texPrompt/<name>.md`
 * (`scripts/tex-prompt-module.mjs`), and, as `train-<nodeId>`, each node's Training examples
 * (`texTraining.cjs`, from `apps/mcp/bench/sets/training`). A node with no Training labels has no words, so a step
 * that names it is given nothing extra.
 */
const TEX_PROMPT = PROMPT.modules;
/**
 * The Training words a config's steps name: `train-<nodeId>` for every node's short examples, and, for each
 * `train:<nodeId>:all:<chars>` entry a step lists, `train-<nodeId>-all-<chars>` (its whole conversations within that
 * cap). A Lab draft that names another cap is given its own words by `texWords`.
 */
function trainingWords(config) {
  const entries = [...config.nodes.map((node) => `train:${node.id}`), ...config.nodes.flatMap((node) => (node.ctx ?? []).filter((entry) => TRAIN_ENTRY.test(entry)))];
  return Object.fromEntries([...new Set(entries)].map((entry) => [trainName(entry), moduleText(entry, TRAINING)]).filter(([, text]) => text !== ""));
}
const TRAINING_WORDS = trainingWords(CONFIG);
export const TEX_PROMPT_WORDS = { ...TEX_PROMPT, ...TRAINING_WORDS };

/** The context entry that names a prompt module: `p-<name>`. */
const PROMPT_ENTRY = /^p-([a-z][a-z0-9-]{0,47})$/;

/**
 * The steps whose code reads the Training modules their context names (`train:<nodeId>`): Decide in the judge's state
 * (`textDecide.cjs`), the router in its state (`routerContext.js`), the front door and the background job among their
 * prompt modules (`texModules`), and every
 * other step whose prompt goes through `withArchitecture` after its own words (`texArchitecture.js`). The suite
 * refuses a `train:` entry on any other step (`texTraining.test.mjs`), so the config never says a step reads examples
 * it is not given.
 */
export const TRAINING_READERS = Object.freeze(["decide", "router", "fd", "job", "advisor", "mailadv", "jobcheck", "jobadv", "planner", "classifier", "reviewer", "handback", "mail", "card", "selfreview", "checkin"]);

/**
 * Every accessor below takes the config to read, main's by default. A Lab test chat's turn passes its draft's
 * (`texConfigOf`), so the draft's models, efforts, time limits and prompt words are the ones that run there; every
 * other turn reads main's, exactly as before.
 */

/**
 * One step of the config by its id, or a retired step's last definition (`RETIRED_STEPS`, always off) when the config
 * has none. Throws for an id neither has: a typo here must fail the suite, not a turn.
 */
export function texStep(id, config = CONFIG) {
  const step = config.nodes.find((node) => node.id === id) ?? RETIRED_STEPS[id];
  if (!step) throw new Error(`texConfig: no step "${id}"`);
  return step;
}

/**
 * The first of `ids` the config has, for a step that a Lab draft may fold into another (Dev2, 2026-11-16): the code of
 * the reviewer reads `texPick(["answerCheck", "reviewer"], config)`, so a draft's Answer check sets it and main's config
 * its Reply reviewer. Throws when it has none of them.
 */
export function texPick(ids, config = CONFIG) {
  const id = ids.find((one) => config.nodes.some((node) => node.id === one));
  if (id === undefined) throw new Error(`texConfig: no step "${ids.join('" or "')}"`);
  return id;
}

/** The gateway model id a step runs on. */
export function texModel(id, config = CONFIG) {
  const step = texStep(id, config);
  const model = config.models[step.model];
  if (typeof model !== "string") throw new Error(`texConfig: step "${id}" runs on "${step.model}", which names no model`);
  return model;
}

/**
 * How hard a step thinks, as the request carries it: `{ effort }`, or for a step at effort `off`,
 * `{ effort: "low", thinking: "off" }` (thinking off, the lowest effort beside it, as the classifier has always run).
 */
export function texEffort(id, config = CONFIG) {
  const effort = texStep(id, config).effort;
  if (effort === "off") return { effort: "low", thinking: "off" };
  if (typeof effort !== "string") throw new Error(`texConfig: step "${id}" has no effort`);
  return { effort };
}

/**
 * How long a step's cached prompt prefix is kept, "1h" or "5m" (`aiGateway.js` `gatewayBody`): the step's `cacheTtl`,
 * an hour when it sets none. Set the front door's to "5m" to go back to five minutes without a code change.
 */
export function texCacheTtl(id, config = CONFIG) {
  return texStep(id, config).cacheTtl === "5m" ? "5m" : "1h";
}

/** Which tools a step's model is shown: "fixed", every tool its kind of chat has (`sixToolsFixed.js`), or "turn", what the turn holds. */
export function texToolList(id, config = CONFIG) {
  return texStep(id, config).toolList === "fixed" ? "fixed" : "turn";
}

/** When a step's rarely-changing modules are read (`frozenModules.js`): "summary", once a day until the next summary, or "turn", each turn. */
export function texFreeze(id, config = CONFIG) {
  return texStep(id, config).freeze === "summary" ? "summary" : "turn";
}

/** A step's time limit in milliseconds. Throws when the file gives it none. */
export function texTimeoutMs(id, config = CONFIG) {
  const seconds = texStep(id, config).timeoutS;
  if (!(typeof seconds === "number" && seconds > 0)) throw new Error(`texConfig: step "${id}" has no time limit`);
  return seconds * 1000;
}

/** The prompt words a config's steps read: the repository's, with a Lab draft's own words over them. */
export function texWords(config = CONFIG) {
  const words = config === CONFIG ? TEX_PROMPT_WORDS : { ...TEX_PROMPT_WORDS, ...trainingWords(config) };
  return config.words ? { ...words, ...config.words } : words;
}

/**
 * The texting setup's model lines, as `production.js` reads a setup note's front matter: `models` (main, effort,
 * advisor, advisor_effort, fallback, job_effort when the job's differs), `plan_big_asks` and `reply_judge`. The
 * advisor's four roles share one model and effort in code, so the advisor step names them.
 */
export function texSetupFront(config = CONFIG) {
  const fd = texStep("fd", config);
  const job = texStep("job", config);
  const advisor = texStep("advisor", config);
  const models = { main: texModel("fd", config), effort: fd.effort };
  if (job.effort !== fd.effort) models.job_effort = job.effort;
  if (advisor.on) Object.assign(models, { advisor: texModel("advisor", config), advisor_effort: advisor.effort });
  // A fallback model is the front door's own setting in a draft that sets it (Dev2, 2026-11-16); main's, the Fallback step.
  if (typeof fd.fallback === "string" && typeof config.models[fd.fallback] === "string") models.fallback = config.models[fd.fallback];
  else if (texStep("fallback", config).on) models.fallback = texModel("fallback", config);
  const front = { models };
  if (texStep("planner", config).on) front.plan_big_asks = "on";
  front.reply_judge = texStep(texPick(["answerCheck", "reviewer"], config), config).on ? "haiku" : "off";
  return front;
}

/**
 * Which prompt modules each kind of turn is built from, in order, as `promptModules.js` reads a setup's `modules:`:
 * the `p-<name>` entries of the front door's context for a 1:1 text and a group (one step answers both), and of the
 * background job's for a job, with each `train:<nodeId>` entry where it stands as `train-<nodeId>` when that node has
 * Training labels. Throws when a step names a module the repository has no words for.
 */
export function texModules(config = CONFIG) {
  const words = texWords(config);
  const named = (entry) => PROMPT_ENTRY.exec(entry)?.[1] ?? (TRAIN_ENTRY.test(entry) && typeof words[trainName(entry)] === "string" ? trainName(entry) : null);
  const of = (id) => {
    // In the order the step runs its reads (`texModuleChange.cjs`): a module that changes less never sits below one that changes more.
    const names = runOrder(texStep(id, config).ctx ?? []).map(named).filter(Boolean);
    if (names.length === 0) throw new Error(`texConfig: step "${id}" reads no prompt module`);
    for (const name of names) if (typeof words[name] !== "string") throw new Error(`texConfig: step "${id}" reads module "${name}", which has no words`);
    return names;
  };
  const texts = of("fd");
  // The specialist doors a config draws (`doorTools.js`): each its own node's modules, or the front door's with its own module added.
  const doors = {};
  for (const route of DOORS) {
    const id = DOOR_NODES[route];
    if (!config.nodes.some((node) => node.id === id)) continue;
    const own = runOrder(texStep(id, config).ctx ?? []).map(named).filter(Boolean);
    const names = own.length > 0 ? own : [...texts, `door-${route}`];
    for (const name of names) if (typeof words[name] !== "string") throw new Error(`texConfig: door "${id}" reads module "${name}", which has no words`);
    doors[`door-${route}`] = names;
  }
  return { texts, group: texts, job: of("job"), ...doors };
}

const EFFORTS = new Set(SCHEMA_EFFORTS);
const MAX_WORDS = 40_000;
const MAX_TIMEOUT_S = 600;

/** A draft's words for its prompt modules (`graph.modules["p-<name>"].text`), as Promote would write them, or `{}`. */
function draftWords(modules) {
  const words = {};
  for (const [key, edit] of Object.entries(modules && typeof modules === "object" ? modules : {})) {
    const name = PROMPT_ENTRY.exec(key)?.[1];
    if (name === undefined || !edit || typeof edit.text !== "string") continue;
    const text = edit.text.replace(/^\uFEFF/, "").trim();
    if (text === "" || text.length > MAX_WORDS || /^---\r?\n/.test(text) || text === TEX_PROMPT_WORDS[name]) continue;
    words[name] = text;
  }
  return words;
}

/** A draft step over main's: each field the draft sets that this config can run, else main's. */
function draftStep(node, edit, config, words) {
  if (!edit) return node;
  const out = { ...node };
  if (typeof edit.on === "boolean") out.on = edit.on;
  // A model main's table names (a Lab-only model has no gateway id, and Promote refuses it too); a code step stays code.
  if (node.model !== "code" && typeof edit.model === "string" && edit.model !== "code" && typeof config.models[edit.model] === "string") out.model = edit.model;
  if (typeof edit.effort === "string" && EFFORTS.has(edit.effort)) out.effort = edit.effort;
  // The front door's fallback model, a model main's table names, or none (Dev2, 2026-11-16: a setting of the step).
  if (node.id === "fd" && (edit.fallback === null || (typeof edit.fallback === "string" && typeof config.models[edit.fallback] === "string"))) out.fallback = edit.fallback;
  // Which tools the step is shown (`sixToolsFixed.js`): what its turn holds, or the fixed list of its kind of chat.
  if (edit.toolList === "fixed" || edit.toolList === "turn") out.toolList = edit.toolList;
  // When its rarely-changing modules are read (`frozenModules.js`): each turn, or once a day until the next summary.
  if (edit.freeze === "summary" || edit.freeze === "turn") out.freeze = edit.freeze;
  if (typeof edit.timeoutS === "number" && edit.timeoutS > 0 && edit.timeoutS <= MAX_TIMEOUT_S && node.timeoutS > 0) out.timeoutS = edit.timeoutS;
  // What the step reads, when every prompt module it names has words here or in the draft.
  if (Array.isArray(edit.ctx) && edit.ctx.every((entry) => typeof entry === "string" && (PROMPT_ENTRY.exec(entry) === null || typeof words[PROMPT_ENTRY.exec(entry)[1]] === "string"))) out.ctx = edit.ctx;
  return out;
}

/** A step the draft adds whose code is merged ahead (`SHELF_NODES`): as the draft draws it, its model main's table names. */
function aheadStep(edit, config) {
  const model = edit.model === "code" || typeof config.models[edit.model] === "string" ? edit.model : "haiku-5-5";
  return { ...edit, model, on: edit.on !== false };
}

/** Whether every wire names a step of `ids` and has a mode, so a draft's wires can run as drawn. */
const wiresRun = (edges, ids) => Array.isArray(edges) && edges.length > 0 && edges.every((e) => e && ids.has(e.from) && ids.has(e.to) && typeof e.mode === "string");

/**
 * A Lab draft over the config, for a Lab test chat's turn only (`labSandbox/policy.js` `sandboxGateOf`): each step's
 * on/off, model, effort, time limit and context as the draft has them, the draft's prompt words as `words`, the steps
 * it adds whose code is merged ahead (`SHELF_NODES`) as it draws them, and its wires when every one names a step that
 * can run. A step the draft takes out stays, for the settings code reads off it, but no wire of the draft reaches it, so
 * it never runs as a step. What the gateway could not run is main's (`draftStep`). A real turn's env carries no gate,
 * so it never reaches here.
 */
export function withDraft(config, draft) {
  if (!draft || typeof draft !== "object" || !Array.isArray(draft.nodes)) return config;
  const own = draftWords(draft.modules);
  const words = { ...TEX_PROMPT_WORDS, ...own };
  const mains = new Set(config.nodes.map((node) => node.id));
  const ahead = new Set(SHELF_NODES);
  const drawn = draft.nodes.filter((node) => node && typeof node.id === "string");
  const byId = new Map(drawn.map((node) => [node.id, node]));
  const added = drawn.filter((node) => !mains.has(node.id) && ahead.has(node.id)).map((node) => aheadStep(node, config));
  const stepped = [...config.nodes.map((node) => draftStep(node, byId.get(node.id), config, words)), ...added];
  const runs = new Set(stepped.map((node) => node.id));
  if (!wiresRun(draft.edges, runs)) return { ...config, nodes: stepped, ...(Object.keys(own).length > 0 ? { words: own } : {}) };
  // The draft's wires run, so what they carry is the draft's too: each step's input and output shape as it draws them.
  const shaped = (node) => {
    const edit = byId.get(node.id);
    if (!edit) return node;
    const out = { ...node };
    for (const key of ["inSchema", "outSchema"]) if (Array.isArray(edit[key])) out[key] = edit[key];
    return out;
  };
  const groups = draft.groups && typeof draft.groups === "object" ? { groups: draft.groups } : {};
  return { ...config, nodes: stepped.map(shaped), edges: draft.edges, ...groups, ...(Object.keys(own).length > 0 ? { words: own } : {}) };
}

/**
 * What of a draft a Lab test chat can run as drawn, and what it runs instead (Dev2, 2026-11-14: only what ran is shown;
 * a test chat on a draft that merged steps ran main's steps without saying so, 2026-11-16). `withDraft` runs only the
 * steps this config has code for and main's wires when one of the draft's names a step it lacks, so:
 *
 *  - `noCode`: steps the draft adds that have no code here; they cannot run until a code change builds them;
 *  - `removed`: main's steps the draft takes out; they still run as main's (each run says which did);
 *  - `wires`: "draft" or "main", and `badWires` the draft's wires naming a step this config has no code for;
 *  - `unapplied`: a step's setting the draft changes that the gateway could not take (a Lab-only model, a prompt module
 *    with no words), run as main's.
 *
 * `asDrawn` is true only when none of these is so. Not a guess: the same rules `withDraft` applies.
 */
export function draftFit(config, draft) {
  if (!draft || typeof draft !== "object" || !Array.isArray(draft.nodes)) return { asDrawn: true };
  const mains = new Set(config.nodes.map((node) => node.id));
  const ahead = new Set(SHELF_NODES);
  const label = (node) => (typeof node?.label === "string" && node.label !== node.id ? `${node.id} (${node.label})` : node.id);
  const drawn = draft.nodes.filter((node) => node && typeof node.id === "string");
  const drawnIds = new Set(drawn.map((node) => node.id));
  const ids = new Set([...mains, ...drawn.filter((node) => ahead.has(node.id)).map((node) => node.id)]); // what can run: main's steps, and the draft's built ahead
  const noCode = drawn.filter((node) => !ids.has(node.id)).map(label);
  const edges = Array.isArray(draft.edges) ? draft.edges : [];
  const badWires = edges.filter((e) => !(e && ids.has(e.from) && ids.has(e.to) && typeof e.mode === "string")).map((e) => `${e?.from ?? "?"} → ${e?.to ?? "?"}`);
  const wires = edges.length > 0 && badWires.length === 0 ? "draft" : "main";
  // A step the draft removes runs no more once its wires run: none reaches it. With main's wires, it still runs as main's.
  const removed = wires === "draft" ? [] : config.nodes.filter((node) => !drawnIds.has(node.id)).map(label);
  const words = { ...TEX_PROMPT_WORDS, ...draftWords(draft.modules) };
  const unapplied = [];
  for (const node of config.nodes) {
    const edit = drawn.find((d) => d.id === node.id);
    if (!edit) continue;
    const ran = draftStep(node, edit, config, words);
    for (const key of ["model", "effort", "timeoutS"]) if (edit[key] !== undefined && edit[key] !== node[key] && ran[key] === node[key]) unapplied.push(`${node.id}.${key} ${JSON.stringify(edit[key])}`);
    if (Array.isArray(edit.ctx) && JSON.stringify(edit.ctx) !== JSON.stringify(node.ctx ?? []) && ran.ctx === node.ctx) unapplied.push(`${node.id}.ctx (a prompt module it names has no words)`);
  }
  const asDrawn = noCode.length === 0 && removed.length === 0 && wires === "draft" && unapplied.length === 0;
  if (asDrawn) return { asDrawn: true };
  return {
    asDrawn: false,
    ...(noCode.length ? { noCode } : {}),
    ...(removed.length ? { removed } : {}),
    wires,
    ...(badWires.length ? { badWires: badWires.slice(0, 20) } : {}),
    ...(unapplied.length ? { unapplied } : {}),
    says: [
      noCode.length ? `${noCode.length} step${noCode.length === 1 ? "" : "s"} the draft adds ha${noCode.length === 1 ? "s" : "ve"} no code yet and cannot run` : null,
      removed.length ? `${removed.length} step${removed.length === 1 ? "" : "s"} the draft removes still run${removed.length === 1 ? "s" : ""} as main's` : null,
      wires === "main" && edges.length ? "its wires name steps with no code, so main's wires run" : null,
      unapplied.length ? `${unapplied.length} setting${unapplied.length === 1 ? "" : "s"} could not be applied and run${unapplied.length === 1 ? "s" : ""} as main's` : null,
    ].filter(Boolean).join("; ") + ". A test chat on it runs main's code for those, not the draft as drawn.",
  };
}

/** Per gate: its draft over main's, made once. */
const drafted = new WeakMap();

/** The config a request's turn runs on: a Lab test chat's draft over main's (`withDraft`), else main's itself. */
export function texConfigOf(env) {
  const gate = sandboxGateOf(env);
  if (gate === null || !gate.config) return CONFIG;
  if (!drafted.has(gate)) drafted.set(gate, withDraft(CONFIG, gate.config));
  return drafted.get(gate);
}
